    {
      "id": "R1",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "세포가 죽는 방식이라는 같은 기준에서 외부 요인에 의한 괴사와 능동적인 세포자멸사를 대비한다."
    },
    {
      "id": "R2",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "세포가 내부 효소로 자신을 파괴한다는 사실이 세포자멸사를 능동적 죽음이라고 판단하는 근거가 된다."
    },
    {
      "id": "R3",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "올챙이의 꼬리 소실은 불필요한 세포를 제거하는 세포자멸사의 구체적인 사례이다."
    },
    {
      "id": "R4",
      "type": "CAUSE",
      "otherName": "",
      "reason": "유해한 비정상적 세포를 제거하는 작용이 실제로 질병으로부터 신체를 보호하는 효과로 이어진다."
    },
    {
      "id": "R5",
      "type": "OTHER",
      "otherName": "기능 병렬",
      "reason": "두 문장은 세포자멸사의 서로 다른 제거 기능을 추가로 나열하며, 어느 한쪽이 다른 쪽의 사례나 구성 요소인 관계는 아니다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "자외선에 의한 DNA 손상은 Bcl-2 농도가 감소하는 상황에 포함된 세포 손상의 구체적인 사례이다."
    },
    {
      "id": "R7",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "호르몬 부족은 Bcl-2 농도 감소에 앞서는 세포 손상 상황을 구체적으로 보여 주는 사례이다."
    },
    {
      "id": "R8",
      "type": "CAUSE",
      "otherName": "",
      "reason": "세포 손상에 따라 감소한 Bcl-2가 미토콘드리아 막의 파괴로 이어지는 실제 작용을 설명한다."
    },
    {
      "id": "R9",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "Bcl-2가 세포자멸사를 억제한다는 기능이 그 단백질의 감소 뒤 막 파괴가 일어나는 이유를 뒷받침한다."
    },
    {
      "id": "R10",
      "type": "CAUSE",
      "otherName": "",
      "reason": "미토콘드리아 막의 파괴가 내부 물질의 방출을 실제로 일으킨다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "미토콘드리아에서 방출된 물질이 카스파제를 활성화하는 직접적인 작용을 한다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "카스파제의 활성화와 자멸사 실행을 카스파제-9와 실행 카스파제의 구체적인 작용으로 풀어 설명한다."
    },
    {
      "id": "R13",
      "type": "CAUSE",
      "otherName": "",
      "reason": "실행 카스파제의 활성화가 DNA의 절단과 붕괴를 일으키므로 단순한 단계 순서 이상의 인과관계이다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "손상된 세포를 제거한다는 일반적인 기능을 Bcl-2 감소와 카스파제 활성화의 세부 기전으로 구체화한다."
    },
    {
      "id": "R15",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "유해한 비정상적 세포를 제거한다는 설명을 바이러스 감염 세포에 대한 T세포의 작용으로 구체화한다."
    },
    {
      "id": "R16",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "세포독성 T세포의 작용은 유해한 세포에 세포자멸사가 유도되는 구체적인 경우이다."
    },
    {
      "id": "R17",
      "type": "PROCESS",
      "otherName": "",
      "reason": "감염으로 표면에 나타난 바이러스 단백질을 다음 단계에서 T세포가 인식하는 과정으로 이어진다."
    },
    {
      "id": "R18",
      "type": "PROCESS",
      "otherName": "",
      "reason": "비정상 단백질을 인식한 뒤 감염 세포에 결합하는 처리 단계의 순서를 제시한다."
    },
    {
      "id": "R19",
      "type": "PROCESS",
      "otherName": "",
      "reason": "감염 세포에 결합한 다음 구멍을 뚫는 단백질을 분비하는 단계로 진행된다."
    },
    {
      "id": "R20",
      "type": "PROCESS",
      "otherName": "",
      "reason": "단백질 분비로 형성된 구멍을 바탕으로 과립효소 B를 유입시키는 다음 단계가 진행된다."
    },
    {
      "id": "R21",
      "type": "CAUSE",
      "otherName": "",
      "reason": "세포 안으로 유입된 과립효소 B가 실행 카스파제를 실제로 활성화한다."
    },
    {
      "id": "R22",
      "type": "CAUSE",
      "otherName": "",
      "reason": "과립효소 B에 의한 실행 카스파제의 활성화가 감염 세포의 DNA 붕괴로 이어진다."
    },
    {
      "id": "R23",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "세포자멸사의 유도 경로라는 같은 기준에서 Bcl-2 감소를 통한 경로와 T세포의 과립효소 B를 통한 경로를 대비한다."
    },
    {
      "id": "R24",
      "type": "OTHER",
      "otherName": "공통 작용",
      "reason": "서로 다른 두 경로가 실행 카스파제에 의한 DNA 붕괴라는 같은 작용을 공유하며, 이는 인물이나 이론 사이의 견해 일치가 아니다."
    },
    {
      "id": "R25",
      "type": "CAUSE",
      "otherName": "",
      "reason": "실행 카스파제에 의한 DNA 붕괴가 사다리 모양이라는 특징의 출현으로 이어진다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "감염 세포에서도 실행 카스파제에 의한 DNA 붕괴가 사다리 모양의 출현으로 이어진다."
    },
    {
      "id": "R27",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "자멸사한 세포의 DNA 특징에서 세포와 핵의 형태 변화로 설명의 초점이 옮겨 간다."
    },
    {
      "id": "R28",
      "type": "PROCESS",
      "otherName": "",
      "reason": "세포 파편화 이후 세포막의 두 층이 뒤섞인다는 시간적 순서를 제시한다."
    },
    {
      "id": "R29",
      "type": "CAUSE",
      "otherName": "",
      "reason": "세포막 두 층의 뒤섞임이 포스파티딜세린의 바깥쪽 노출로 이어지는 실제 변화를 설명한다."
    },
    {
      "id": "R30",
      "type": "CAUSE",
      "otherName": "",
      "reason": "노출된 포스파티딜세린이 식세포의 자멸사 세포 인식을 일으키는 표지로 작용한다."
    },
    {
      "id": "R31",
      "type": "PROCESS",
      "otherName": "",
      "reason": "식세포가 자멸사한 세포를 인식한 다음 그 세포를 포식하는 단계로 진행된다."
    },
    {
      "id": "R32",
      "type": "CAUSE",
      "otherName": "",
      "reason": "신속한 포식 처리가 염증 유발 물질의 누출을 막아 염증 반응이 발생하지 않게 하는 실제 기전을 설명한다."
    },
    {
      "id": "R33",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "괴사와 세포자멸사의 차이에 관한 논의가 죽음의 방식에서 염증 반응의 유발 여부로 확장된다."
    },
    {
      "id": "R34",
      "type": "CAUSE",
      "otherName": "",
      "reason": "비정상적 세포의 적시 제거가 새로운 세포의 생성으로 이어진다고 설명한다."
    },
    {
      "id": "R35",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "결말에서 비정상적 세포를 제거한다는 앞선 기능 설명을 다시 진술한다."
    },
    {
      "id": "R36",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "세포자멸사의 질병 방어 기능을 악성 종양 등 질병의 치료 방안 연구에 활용한다."
    }
  ]
}

